package br.com.bemdoar.controller;
import br.com.bemdoar.dto.*;import br.com.bemdoar.security.UsuarioAutenticado;import br.com.bemdoar.service.*;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api")public class CandidaturaController{private final CandidaturaService s;public CandidaturaController(CandidaturaService s){this.s=s;}private Long uid(Authentication a){return ((UsuarioAutenticado)a.getPrincipal()).getId();}private boolean admin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMINISTRADOR"));}@PostMapping("/candidaturas")public CandidaturaResponse criar(@RequestParam Long oportunidadeId,Authentication a){return s.criar(uid(a),oportunidadeId);}@GetMapping("/candidaturas/minhas")public List<CandidaturaResponse> minhas(Authentication a){return s.minhas(uid(a));}@GetMapping("/oportunidades/{id}/candidaturas")@PreAuthorize("hasRole('ADMINISTRADOR')")public List<CandidaturaResponse> lista(@PathVariable Long id){return s.porOportunidade(id);}@PatchMapping("/candidaturas/{id}/aprovar")@PreAuthorize("hasRole('ADMINISTRADOR')")public CandidaturaResponse aprovar(@PathVariable Long id){return s.aprovar(id);}@PatchMapping("/candidaturas/{id}/recusar")@PreAuthorize("hasRole('ADMINISTRADOR')")public CandidaturaResponse recusar(@PathVariable Long id,@RequestBody(required=false)CancelamentoRequest q){return s.recusar(id,q);}@PatchMapping("/candidaturas/{id}/cancelar")public CandidaturaResponse cancelar(@PathVariable Long id,Authentication a){return s.cancelar(id,uid(a),admin(a));}@PostMapping("/candidaturas/{id}/participacao")@PreAuthorize("hasRole('ADMINISTRADOR')")public CandidaturaResponse participacao(@PathVariable Long id,@Valid @RequestBody ParticipacaoRequest q){return s.participacao(id,q);}}
